WITH filtered AS (SELECT id, category, brand, cost, stock_qty, launch_date, tags, supplier_id, LEAST(cost, stock_qty) AS least_cost_stock_qty, COALESCE(brand, 'OTHER') AS resolved_brand FROM products WHERE launch_date > TO_DATE('2023-09-12') AND brand IS NOT NULL AND price > 930) SELECT CASE WHEN cost >= 630 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, CASE WHEN least_cost_stock_qty >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END AS least_cost_stock_qty_tier, DATE_TRUNC('MONTH', launch_date) AS activity_month, COUNT(DISTINCT supplier_id) AS distinct_supplier_ids, SUM(stock_qty) FILTER (WHERE brand = 'Acme') AS acme_total_stock_qty FROM filtered GROUP BY CASE WHEN cost >= 630 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN least_cost_stock_qty >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('MONTH', launch_date) HAVING acme_total_stock_qty < 0
